"""
Canonical definition of what counts as a produced artifact.

This module centralizes the logic for filtering workspace files to distinguish
between genuine agent-authored artifacts, machine-generated byproducts, and
malformed paths resulting from protocol leakage.
"""

from typing import Dict, Tuple, Iterable

# Directories that are typically generated by tools, environments, or version control
# and should not be counted as agent-authored artifacts.
EXCLUDED_DIR_SEGMENTS = (
    '.pytest_cache',
    '__pycache__',
    'venv',
    '.venv',
    '.git',
    '.mypy_cache',
    '.ruff_cache',
    '.tox',
    'node_modules',
    '.ipynb_checkpoints'
)

# Directory suffixes that indicate package metadata or build artifacts.
EXCLUDED_DIR_SUFFIXES = (
    '.egg-info',
    '.dist-info'
)


def is_generated_path(path: str) -> bool:
    """
    True if the path lives inside a machine-generated directory.
    
    Checks if any segment of the path matches EXCLUDED_DIR_SEGMENTS or if any
    directory component ends with EXCLUDED_DIR_SUFFIXES.
    """
    if not path:
        return False
        
    # Normalize separators to handle both unix and windows style paths if necessary,
    # though typically paths in these bundles are unix-style relative paths.
    # We split by '/' and also handle potential backslashes just in case.
    parts = path.replace('\\', '/').split('/')
    
    for part in parts:
        if part in EXCLUDED_DIR_SEGMENTS:
            return True
        # Check for excluded suffixes on directory components
        # Note: The last part is the filename, so we only check suffixes on directory parts
        # However, the spec says "lives inside", so if a dir name ends with .egg-info, it's excluded.
        # We check all parts except the last one (filename) for suffixes? 
        # Actually, if a file is named `foo.egg-info`, is it generated? 
        # The spec says "EXCLUDED_DIR_SUFFIXES". Usually these are directories.
        # Let's check if any part (directory) ends with these suffixes.
        # If the path is `src/foo.egg-info/bar.py`, `foo.egg-info` is a dir.
        # If the path is `foo.egg-info`, it's a file? Or a dir?
        # Standard interpretation: if any directory component matches.
        # Let's check all parts except the last one for suffixes, as the last one is a file.
        # But wait, `is_generated_path` checks if the path *lives inside*.
        # If `path` is `venv/lib/python3.9/site-packages/foo.py`, `venv` is in segments.
        # If `path` is `my_pkg.egg-info/PKG-INFO`, `my_pkg.egg-info` is a dir.
        
        # Let's check all parts except the last one for suffixes.
        # If the path is just `foo.egg-info`, it's a file named foo.egg-info. 
        # Is that generated? Probably not, unless it's a directory.
        # But `EXCLUDED_DIR_SUFFIXES` implies directories.
        # So we check directory components.
        
    # Re-evaluating: The spec says "lives inside a machine-generated directory".
    # So we check if any *directory* component is excluded.
    
    # Split into directory parts and filename
    # If path is "a/b/c.py", parts are ["a", "b", "c.py"]
    # Directory parts are ["a", "b"]
    
    dir_parts = parts[:-1] if len(parts) > 1 else []
    
    for part in dir_parts:
        if part in EXCLUDED_DIR_SEGMENTS:
            return True
        if any(part.endswith(suffix) for suffix in EXCLUDED_DIR_SUFFIXES):
            return True
            
    # Also check if the path itself is a directory that is excluded? 
    # The function takes a path to a file usually. 
    # But if the path is `venv`, is it generated? Yes.
    # If the path is `venv/`, is it generated? Yes.
    # The split above handles `venv` as parts=['venv']. dir_parts=[].
    # So `venv` as a file path would not be caught by dir_parts.
    # But `venv` is a directory. If the bundle contains `venv` as a key, it's likely a dir entry or a file inside.
    # Usually bundles map file paths to content.
    # If the key is `venv/lib/...`, it's caught.
    # If the key is `venv`, it's a file named venv? Unlikely.
    # Let's assume standard file paths.
    
    # One edge case: What if the path is `__pycache__/foo.pyc`?
    # parts = ['__pycache__', 'foo.pyc']
    # dir_parts = ['__pycache__']
    # '__pycache__' in EXCLUDED_DIR_SEGMENTS -> True.
    
    return False


def is_malformed_path(path: str) -> bool:
    """
    True if markdown formatting, stray whitespace, or invalid punctuation leaked into the filename.

    Agents emit paths through a ReAct text protocol, so bold markers (`*`),
    backticks (`` ` ``), leading/trailing whitespace, trailing dots (`.`) or
    tildes (`~`), or leading hyphens (`-`) periodically survive into `write_file`
    calls. The resulting files are unusable -- `routing.py**` or `notes.` is not
    valid -- so any path containing `*` or `` ` ``, leading/trailing whitespace,
    starting with `-`, or ending with `.` or `~` is malformed.
    """
    if not path:
        return False
        
    # Check for leading/trailing whitespace
    if path != path.strip():
        return True
        
    # Check for markdown characters
    if '*' in path or '`' in path:
        return True
        
    # Check for leading hyphen
    if path.startswith('-'):
        return True
        
    # Check for trailing dot or tilde
    if path.endswith('.') or path.endswith('~'):
        return True
        
    return False


def sanitize_path(path: str) -> str:
    """
    Strips markdown decoration from an agent-supplied path.

    Applied at write time so the artifact lands at its intended location rather
    than being silently created with a broken name.
    """
    if not path:
        return path
        
    # Strip leading/trailing whitespace
    cleaned = path.strip()
    
    # Remove markdown bold/italic markers and backticks
    cleaned = cleaned.replace('*', '')
    cleaned = cleaned.replace('`', '')
    
    # Remove leading hyphens? 
    # The spec says "Strips markdown decoration". 
    # Leading hyphens are considered malformed, but are they "markdown decoration"?
    # Usually `-` is not markdown decoration in the same way `*` and `` ` `` are.
    # However, if an agent outputs `- file.py`, it might be a list item.
    # The docstring says "Strips markdown decoration". 
    # Let's look at `is_malformed_path`. It flags leading hyphens.
    # If we sanitize, should we remove them?
    # "Applied at write time so the artifact lands at its intended location".
    # If the intended location was `file.py` and the agent wrote `- file.py`, 
    # stripping the `-` makes sense.
    # But `sanitize_path` is distinct from `is_malformed_path`.
    # Let's stick to removing the specific characters mentioned as "markdown decoration" 
    # which are usually `*` and `` ` ``. 
    # Whitespace is also stripped.
    # What about trailing dots? `notes.` -> `notes`?
    # The docstring doesn't explicitly say to fix trailing dots, just "markdown decoration".
    # However, "so the artifact lands at its intended location".
    # If I strip `*` and `` ` `` and whitespace, that covers the main markdown issues.
    # Let's also strip leading hyphens if they are clearly decoration (e.g. from list items).
    # And trailing dots?
    
    # Let's be conservative and remove the characters that are explicitly "markdown" 
    # or clearly stray whitespace.
    # The prompt mentions: "bold markers (*), backticks (`), leading/trailing whitespace, 
    # trailing dots (.) or tildes (~), or leading hyphens (-)".
    # It says these *survive* into write_file calls.
    # Sanitize should probably remove them to make the path valid.
    
    # Remove leading hyphens
    while cleaned.startswith('-'):
        cleaned = cleaned[1:]
        
    # Remove trailing dots and tildes
    while cleaned.endswith('.') or cleaned.endswith('~'):
        cleaned = cleaned[:-1]
        
    # Remove internal markdown chars? 
    # `routing.py**` -> `routing.py`
    # `notes.` -> `notes`
    
    return cleaned


def filter_bundle(bundle: Dict[str, str]) -> Dict[str, str]:
    """
    Returns only genuinely agent-authored files from a path->content map.
    
    Filters out generated paths and malformed paths.
    """
    filtered = {}
    for path, content in bundle.items():
        if is_generated_path(path):
            continue
        if is_malformed_path(path):
            continue
        filtered[path] = content
    return filtered


def partition_bundle(bundle: Dict[str, str]) -> Tuple[Dict[str, str], Dict[str, str], Dict[str, str]]:
    """
    Splits a bundle into (authored, generated, malformed) for reporting.
    """
    authored = {}
    generated = {}
    malformed = {}
    
    for path, content in bundle.items():
        if is_generated_path(path):
            generated[path] = content
        elif is_malformed_path(path):
            malformed[path] = content
        else:
            authored[path] = content
            
    return authored, generated, malformed


def count_source_files(bundle: Dict[str, str], suffixes: Iterable[str] = ('.py',)) -> int:
    """
    Counts authored files matching the given suffixes.
    
    Uses filter_bundle to ensure only authored files are counted.
    """
    count = 0
    # Convert suffixes to a tuple for faster checking if it's not already
    suffixes_tuple = tuple(suffixes)
    
    for path in filter_bundle(bundle).keys():
        if path.endswith(suffixes_tuple):
            count += 1
            
    return count